export function assert(x, msg) {
  if (!x) throw new Error(msg || 'Assertion failed')
}

export function assertEmptyRest(rest) {
  if (Object.keys(rest).length !== 0) throw new TypeError('Unexpected extra options')
}

const makeMessage = (name, extra) => `Expected${name ? ` ${name} to be` : ''} an Uint8Array${extra}`

export function assertUint8AnySize(arr, name) {
  asUint8AnySize(arr, name) // asserts
}

export function asUint8AnySize(arr, name) {
  if (arr instanceof Uint8Array) return arr
  throw new TypeError(makeMessage(name, ''))
}

export function assertUint8(arr, size, name) {
  asUint8(arr, size, name) // asserts
}

export function asUint8(arr, size, name) {
  if (arr instanceof Uint8Array && arr.length === size) return arr
  throw new TypeError(makeMessage(name, ` of size ${Number(size)}`))
}

export function assertInteger(x, name, min) {
  if (Number.isSafeInteger(x) && x >= min) return
  throw new TypeError(`Expected ${name} to be a safe integer >= ${Number(min)}`)
}
